DO $$ DECLARE historical_id uuid; current_id uuid; BEGIN SELECT DISTINCT r.legal_entity_id INTO STRICT historical_id FROM establishment.group_identifier i JOIN establishment.group_identifier_type t USING(group_identifier_type_id) JOIN establishment.establishment_party_role r USING(establishment_party_role_id) WHERE t.name='Group UID' AND i.value IN('16279','17115'); SELECT r.legal_entity_id INTO STRICT current_id FROM establishment.group_identifier i JOIN establishment.group_identifier_type t USING(group_identifier_type_id) JOIN establishment.establishment_party_role r USING(establishment_party_role_id) WHERE t.name='Group UID' AND i.value='17397'; IF historical_id=current_id OR (SELECT count(*) FROM establishment.legal_entity_address WHERE legal_entity_id=historical_id AND address_purpose_id=3 AND is_current)<>1 OR NOT EXISTS(SELECT 1 FROM establishment.legal_entity_address l JOIN establishment.address a USING(address_id) WHERE l.legal_entity_id=historical_id AND a.address_line_1='Wootton Park School Wootton Hall Park' AND a.address_line_2='Wootton' AND a.town='Northampton' AND a.postcode='NN4 0JA') OR NOT EXISTS(SELECT 1 FROM establishment.legal_entity_address l JOIN establishment.address a USING(address_id) WHERE l.legal_entity_id=current_id AND a.address_line_1='Wootton Park School' AND a.address_line_2='Wootton Hall Park' AND a.town='Northampton' AND a.postcode='NN4 0HZ') THEN RAISE EXCEPTION 'T22 accepted party/address mapping is missing'; END IF; END $$;
SELECT 'T22 group-address checks passed' AS result;
